import fs from 'node:fs'
import path from 'node:path'
import { requireAuth } from '../http/requireAuth.js'

// Written as the first line of every route file generated by make:feature.
export const FEATURE_ROUTE_MARKER = '// @tylix-feature'

const GENERATED_ACTIONS = ['index', 'store', 'show', 'update', 'destroy']

// A route file is "owned" by a feature only when make:feature wrote it.
// Hand-written files that merely share the table name (provisions.ts,
// sites.ts, ...) must NOT suppress the manifest routes.
function isFeatureRouteFile(filePath) {
    let content
    try {
        content = fs.readFileSync(filePath, 'utf8')
    } catch {
        return false
    }

    if (content.includes(FEATURE_ROUTE_MARKER)) return true

    // Legacy: files generated before the marker existed called all five
    // controller actions as `controller.<action>(req, res)`.
    return GENERATED_ACTIONS.every((action) =>
        content.includes(`controller.${action}(req, res)`),
    )
}

function hasRouteFile(baseDir, table) {
    return ['js', 'ts'].some((ext) =>
        isFeatureRouteFile(path.join(baseDir, 'app', 'routes', `${table}.${ext}`)),
    )
}

// Returns the tables that were skipped because a generated route file owns them.
export function registerFeatureRoutes(
    router,
    features,
    { secret, hydrate, baseDir = process.cwd() } = {},
) {
    const skipped = []

    for (const { manifest, controller } of features) {
        if (hasRouteFile(baseDir, manifest.table)) {
            skipped.push(manifest.table)
            continue
        }

        const base = `/api/${manifest.table}`;
        const wrap = (fn) => (manifest.auth ? requireAuth(fn, secret, { hydrate }) : fn);

        router.get(base, wrap((req, res) => controller.index(req, res)));
        router.get(`${base}/:id`, wrap((req, res) => controller.show(req, res)));
        router.post(base, wrap((req, res) => controller.store(req, res)));
        router.put(`${base}/:id`, wrap((req, res) => controller.update(req, res)));
        router.delete(`${base}/:id`, wrap((req, res) => controller.destroy(req, res)));
    }

    return skipped
}